// Documentation site of EBS. Content: src/content/docs (hand-written) and
// src/content/docs/reference (generated by scripts/gen_site_reference.py before dev/build).
import { readFileSync } from 'node:fs';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import starlightLinksValidator from 'starlight-links-validator';

// Shared with scripts/gen_site_reference.py: base path, site origin, repository URL.
const siteConfig = JSON.parse(readFileSync(new URL('./site.config.json', import.meta.url), 'utf-8'));

/** A sidebar group listing every page of a content directory. */
const group = (label, directory) => ({ label, items: [{ autogenerate: { directory } }] });

export default defineConfig({
  site: siteConfig.site,
  base: siteConfig.base,
  trailingSlash: 'always',
  vite: {
    // Pages embed real repository files (examples/, deploy/, integrations/) at build time.
    server: { fs: { allow: ['..'] } },
  },
  integrations: [
    starlight({
      title: 'EBS',
      description:
        'EBS, the EDA Build System: hash-based builds of EDA flows on SLURM with a shared cache, team releases and provenance.',
      logo: { src: './src/assets/logo.svg', replacesTitle: false },
      favicon: '/favicon.svg',
      social: [{ icon: 'github', label: 'GitHub', href: siteConfig.repo }],
      editLink: { baseUrl: `${siteConfig.repo}/edit/main/site/` },
      lastUpdated: true,
      customCss: ['./src/styles/tokens.css', './src/styles/starlight.css'],
      components: {
        // Only the landing page (src/content/docs/index.mdx) has a `hero`.
        Hero: './src/components/landing/Hero.astro',
      },
      // Page order inside a group: each page's `sidebar.order` frontmatter.
      sidebar: [
        group('Start here', 'start'),
        group('Tutorials', 'tutorials'),
        group('Concepts', 'concepts'),
        group('Guides', 'guides'),
        group('Integrations', 'integrations'),
        group('Operate', 'operate'),
        {
          label: 'Reference',
          items: [
            { ...group('CLI', 'reference/cli'), collapsed: true },
            'reference/flow-schema',
            'reference/config',
            'reference/rule-api',
            'reference/toolchain-api',
            'reference/exit-codes',
            'reference/roadmap',
          ],
        },
      ],
      plugins: [
        starlightLinksValidator({
          // Static files served next to the pages (the flow JSON Schema for editors).
          exclude: [`${siteConfig.base}/schemas/**`],
        }),
      ],
    }),
  ],
});
